function resizeComposer(){$('input').style.height='auto';$('input').style.height=Math.min($('input').scrollHeight,140)+'px';updateComposerState()}
function updateComposerState(){$('composer').classList.toggle('responding',busy);$('send').disabled=busy||connecting||!$('input').value.trim();if($('stopReply'))$('stopReply').hidden=!busy}
if($('stopReply'))$('stopReply').onclick=()=>{if(busy)controller.abort()};
$('input').oninput=resizeComposer;$('input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229&&!(window.matchMedia&&window.matchMedia('(pointer: coarse)').matches)){e.preventDefault();if(busy){toast('Your draft is kept while the reply finishes.');return}$('composer').requestSubmit()}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true}};if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline support could not be enabled.'));

function renderMessage(node,content){
  node.replaceChildren();const parts=String(content).split(/(```[\s\S]*?```)/g);
  for(const part of parts){
    if(part.startsWith('```')&&part.endsWith('```')){
      const raw=part.slice(3,-3),nl=raw.indexOf('\n'),language=nl>=0?raw.slice(0,nl).trim():'',code=nl>=0?raw.slice(nl+1):raw;
      const block=document.createElement('div');block.className='code-block';const head=document.createElement('div');head.className='code-head';const lang=document.createElement('span');lang.textContent=language||'code';const copy=document.createElement('button');copy.type='button';copy.textContent='Copy';copy.onclick=async()=>{try{await navigator.clipboard.writeText(code);toast('Code copied.')}catch{toast('Copy unavailable. Select the code to copy it.')}};const pre=document.createElement('pre'),el=document.createElement('code');el.textContent=code;pre.append(el);head.append(lang,copy);block.append(head,pre);node.append(block);
    }else node.append(document.createTextNode(part));
  }
}
function selectModeModel(){
  if(!models.length){updateCodingNotice();return}
  const coding=chooseCodingModel(models,modeModels.coding);
  const chosen=mode==='coding'?(coding||(models.includes(modeModels.coding)?modeModels.coding:modeModels.chat)):modeModels.chat;
  if(models.includes(chosen))$('model').value=chosen;
  modeModels[mode]=$('model').value;updateCodingNotice(coding);
}
function updateCodingNotice(coding=chooseCodingModel(models,modeModels.coding)){
  $('codingNotice').hidden=mode!=='coding';
  $('codingNotice').textContent=!models.length?'Coding workspace · Connect Ollama to detect installed coding models.':coding&&isCodingModel($('model').value)?'Coding model selected · '+$('model').value:!coding?'No recognized coding model installed. Using '+$('model').value+'. Install a model such as qwen2.5-coder, then reconnect.':'Manual model selection · '+$('model').value;
}
$('model').onchange=()=>{stopVoiceForNavigation();modeModels[mode]=$('model').value;savePreferences();updateCodingNotice()};
function switchMode(next){
  stopVoiceForNavigation();if(busy||connecting)return toast('Finish the current response or connection check before switching tabs.');
  if(next!==mode){views[mode]={active,draft:$('input').value};if(models.length)modeModels[mode]=$('model').value;mode=next;active=views[mode].active;if(!chats.some(c=>c.id===active))active=null;$('input').value=views[mode].draft;resizeComposer();selectModeModel();updateModeUI();render();savePreferences()}
  setSidebar(false);$('input').focus();
}
function updateModeUI(){
  const coding=mode==='coding';$('chatsNav').classList.toggle('active',!coding);$('codingNav').classList.toggle('active',coding);$('chatsNav').setAttribute('aria-current',coding?'false':'page');$('codingNav').setAttribute('aria-current',coding?'page':'false');
  document.body.classList.toggle('coding-mode',coding);$('input').placeholder=coding?'Describe what you want to build, debug, or review…':'Ask anything, or think out loud…';
  document.querySelector('#welcome h1').textContent=coding?'A place to build what’s next.':'Your mind. A little further.';
  document.querySelector('#welcome > p').textContent=coding?'Write, debug, and review with your AI.':'A familiar place to think, build, and explore. Powered by your AI. Wherever you are.';
  const prompts=coding?[['⌘','Write some code','Turn a specification into a solution','Help me write code. Ask what I want to build and which language to use.'],['⌕','Find the bug','Work through an error together','Help me debug my code. Ask me to paste the code, the error, and the expected behavior.'],['⎇','Review & improve','Get a second pair of eyes','Review my code for correctness, clarity, and security. Ask me to paste the code.']]:[['✧','Think it through','Make room for a new idea','Help me turn a rough idea into a practical plan.'],['⌘','Build something','From first thought to first draft','Help me build something. Start by asking what I want to create.'],['◎','Follow your curiosity','Find a different perspective','Help me learn something new. Ask what I am curious about.']];
  document.querySelectorAll('[data-prompt]').forEach((button,i)=>{const [icon,title,description,prompt]=prompts[i];button.querySelector('span').textContent=icon;button.querySelector('b').textContent=title;button.querySelector('small').textContent=description;button.dataset.prompt=prompt});updateCodingNotice();
}

updateModeUI();render();updateConnection();

function updateStorageNotice(){
  $('storageNotice').hidden=storage.persistent;
  $('storageNotice').textContent='Device storage is unavailable. Chats are kept only for this session; leave this page open to retain them.';
}
$('installHelp').onclick=()=>openDialog($('installGuide'));
$('closeInstallGuide').onclick=()=>closeDialog($('installGuide'));
const apple=/Mac|iPhone|iPad|iPod/.test(navigator.platform||'');
document.querySelector('.new kbd').textContent=apple?'⌘ K':'Ctrl K';
